// ============================================================================
// Core Token Classes
// ============================================================================

final case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(entries: (String, Any)*): Token = {
    val newMeta = metadata ++ entries.toMap
    copy(metadata = newMeta)
  }
}

object Token {
  def withMetadata(token: Token, entries: (String, Any)*): Token = token.withMetadata(entries: _*)
}

final class MutableTokenBatch(initial: Seq[Token] = Seq.empty) {
  private val buffer: mutable.ListBuffer[Token] = mutable.ListBuffer(initial: _*)
  private var processed: Boolean = false

  def tokens: List[Token] = buffer.toList

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    buffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val stored: Vector[T] = items.toVector

  def getAll: Vector[T] = stored

  def size: Int = stored.size

  def mapTokens[U >: T](func: U => String): List[String] = stored.map(item => func(item)).toList
}

final class TokenSink[-T] {
  private val received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

