      case bd: java.math.BigDecimal =>
        scala.math.BigDecimal(bd).setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString
      case d: java.lang.Double =>
        f"${d.doubleValue()}%1.${precision}f"
      case f: java.lang.Float =>
        f"${f.floatValue()}%1.${precision}f"
      case _ =>
