// Token Registry with Nested Generics
// ============================================================================

final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None =>
        List.empty
      case Some(container) =>
        val results = mutable.ListBuffer.empty[Option[Token]]
        container.getAll.foreach { item =>
          val tokenOpt = handlers.iterator.map(handler => handler(item)).collectFirst {
            case Some(token) => token
          }
          results += tokenOpt
        }
        results.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[T](protected val value: T) {
  def map[B](func: T => B): TokenFunctor[B] = new TokenFunctor(func(value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = func(value)

  def getOrElse(default: T): T = if (value == null) default else value

  def get: T = value
}

final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] = new TokenMonad(funcWrapped.value(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  private val printer: Printer = if (pretty) Printer.spaces2 else Printer.noSpaces

  def tokenize(value: Json): Token = {
    val jsonStr = printer.print(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = if (path.trim.isEmpty) Seq.empty else path.split("\\.").toSeq

    val resolved = parts.foldLeft(Option(value)) { (currentOpt, part) =>
      currentOpt.flatMap { current =>
        current.asObject.flatMap(_.apply(part)).orElse {
          if (part.forall(_.isDigit)) {
            current.asArray.flatMap { arr =>
              val idx = part.toInt
              if (idx >= 0 && idx < arr.size) Some(arr(idx)) else None
            }
          } else {
            None
          }
        }
      }
    }

    resolved.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def stripPunct(word: String): String = {
    val withoutLeading = word.dropWhile(punctuation.contains)
    withoutLeading.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(limit) if normalized.length > limit => normalized.take(limit)
        case _ => normalized
      }

      if (truncated.nonEmpty) Some(truncated) else None
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      processToken(word).foreach { processed =>
        tokens += Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[T => Boolean] = mutable.ListBuffer.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ entries.toMap
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toVector
    val validatorsSnapshot = validators.toVector
    val metadataSnapshot = metadata

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      normalizersSnapshot.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

// ============================================================================
// Utility Functions
// ============================================================================

object TokenizerFunctions {
  def tokenize[T](tokenizer: BaseTokenizer[T], value: T): Token = tokenizer.tokenize(value)

  def tokenizeBatch[T](tokenizer: BaseTokenizer[T], values: Iterable[T]): Iterator[Token] =
    tokenizer.tokenizeBatch(values)

  def toToken(value: Tokenizable): String = value.toToken

  def withMetadata(token: Token, entries: (String, Any)*): Token = token.withMetadata(entries: _*)
}
